prakriya nighantu_kunji_gudh(key, keyn, cap) {
    yadi (cap < 1) { nivartanam 0 }
    vitti h = fnv1a(key, keyn)
    nivartanam h % cap
}

# nighantu_kunji_sam(m, slot, cap, key, keyn) — 1 if slot's key equals (key,keyn)
# (internal helper; keyn already truncated by the caller).
# Reworked in R13 to use khand_tul instead of a hand-rolled loop.

prakriya nighantu_anwesh(m, cap, key, keyn) {
    vitti kn = keyn
    vitti idx = 0
    vitti start = 0
    yadi (cap < 1) { nivartanam 0 - 1 }
    yadi (kn < 0) { nivartanam 0 - 1 }
    yadi (kn > 32) { kn = 32 }
    idx = nighantu_kunji_gudh(key, kn, cap)
    start = idx
    yavat (m[2 + idx] == 1) {
        yadi (nighantu_kunji_sam(m, idx, cap, key, kn) == 1) { nivartanam idx }
        idx = idx + 1
        yadi (idx >= cap) { idx = 0 }
        yadi (idx == start) { nivartanam 0 - 1 }
    }
    nivartanam 0 - 1
}

# nighantu_srij(cap) — allocate and clear a map of capacity cap (clamped to >= 1).
# Returns 0 if cap is so large the allocation size overflows (a
# wrapped size allocated a small buffer and then wrote cap state
# cells past it — SIGSEGV).

prakriya nighantu_khip(m, cap, key, keyn, val) {
    vitti kn = keyn
    vitti idx = 0
    vitti start = 0
    vitti slot = 0
    yadi (cap < 1) { nivartanam 0 }
    yadi (kn < 0) { nivartanam 0 }
    yadi (kn > 32) { kn = 32 }
    slot = nighantu_anwesh(m, cap, key, kn)
    yadi (slot >= 0) {
        m[2 + 2 * cap + slot] = val
        nivartanam 1
    }
    idx = nighantu_kunji_gudh(key, kn, cap)
    start = idx
    yavat (m[2 + idx] == 1) {
        idx = idx + 1
        yadi (idx >= cap) { idx = 0 }
        yadi (idx == start) { nivartanam 0 }
    }
    nighantu_koshtha_likh(m, idx, cap, key, kn, val)
    m[1] = m[1] + 1
    nivartanam 1
}

# nighantu_grah(m, cap, key, keyn) — value stored for key, or -1 if absent
# (documented sentinel; use nighantu_antah to disambiguate).

prakriya nighantu_grah(m, cap, key, keyn) {
    vitti kn = keyn
    vitti slot = 0
    yadi (kn > 32) { kn = 32 }
    slot = nighantu_anwesh(m, cap, key, kn)
    yadi (slot < 0) { nivartanam 0 - 1 }
    nivartanam m[2 + 2 * cap + slot]
}

# nighantu_antah(m, cap, key, keyn) — 1 if key is present, else 0.

prakriya nighantu_antah(m, cap, key, keyn) {
    vitti kn = keyn
    yadi (kn > 32) { kn = 32 }
    yadi (nighantu_anwesh(m, cap, key, kn) < 0) { nivartanam 0 }
    nivartanam 1
}

# nighantu_apanay(m, cap, key, keyn) — delete key; 1 if removed, 0 if absent.
# Backward-shift deletion (Knuth 6.4R): after clearing the slot, each
# following live entry whose home bucket is NOT cyclically past the hole
# is shifted back into it, preserving every probe chain with no
# tombstones.

prakriya nighantu_apanay(m, cap, key, keyn) {
    vitti kn = keyn
    vitti pos = 0
    vitti i = 0
    vitti j = 0
    vitti r = 0
    vitti can_move = 0
    vitti k = 0
    vitti base_i = 0
    vitti base_j = 0
    vitti keyaddr = 0
    vitti kl = 0
    yadi (kn > 32) { kn = 32 }
    pos = nighantu_anwesh(m, cap, key, kn)
    yadi (pos < 0) { nivartanam 0 }
    m[2 + pos] = 0
    m[1] = m[1] - 1
    i = pos
    j = pos + 1
    yadi (j >= cap) { j = 0 }
    yavat (m[2 + j] == 1) {
        kl = m[2 + cap + j]
        base_j = (2 + 3 * cap) * 8 + j * 32
        keyaddr = m + base_j
        r = fnv1a(keyaddr, kl) % cap
        # the entry at j may move into the hole at i iff i lies on the
        # clockwise path from its home bucket r to j
        can_move = 0
        yadi (r <= j) {
            yadi (r <= i) {
                yadi (i <= j) { can_move = 1 }
            }
        } anya {
            yadi (i >= r) {
                can_move = 1
            } anya {
                yadi (i <= j) { can_move = 1 }
            }
        }
        yadi (can_move == 1) {
            base_i = (2 + 3 * cap) * 8 + i * 32
            m[2 + i] = 1
            m[2 + cap + i] = kl
            m[2 + 2 * cap + i] = m[2 + 2 * cap + j]
            # NOTE: not khand_pratilip — its terminator at out[32] would land
            # on the next slot's first key byte.
            k = 0
            yavat (k < 32) {
                akshar_rakh(m, base_i + k, akshar(m, base_j + k))
                k = k + 1
            }
            m[2 + j] = 0
            i = j
        }
        j = j + 1
        yadi (j >= cap) { j = 0 }
    }
    nivartanam 1
}

# nighantu_rikta(m) — reset the map to empty IN PLACE (WS1, R19): same
# handle, same capacity, no leak, no re-allocation. Capacity is read
# from m[0]; no cap parameter, so a mismatched cap cannot corrupt
# the map. FULL ZERO, not a count reset: the count, every state
# flag, every keylen, every val, and every key byte are set to 0.
# After nighantu_rikta the buffer is indistinguishable from a freshly
# zeroed map. Merely resetting the count would leave the old keys
# readable through the key region to anyone holding the handle —
# the stale-segment hazard this closes. Returns 1.

prakriya nighantu_grah_mool(m, cap, key, keyn, def) {
    vitti kn = keyn
    vitti slot = 0
    yadi (kn > 32) { kn = 32 }
    slot = nighantu_anwesh(m, cap, key, kn)
    yadi (slot < 0) { nivartanam def }
    nivartanam m[2 + 2 * cap + slot]
}

# nighantu_maap(m) — number of entries in the map m (its stored size cell).

prakriya nighantu_maap(m) {
    nivartanam m[1]
}

# nighantu_mil(dst, dcap, src, scap) — copy every entry of src into dst;
# src's values overwrite dst's on key conflict (WS3, R23). Returns the
# number of entries merged. If dst fills up, merging stops early and
# the return is less than nighantu_maap(src), the merge is incomplete.
# Destination map size alone cannot detect this: updates need not change it.
# Keys come from nighantu_kunjika_ashtak, so each is known to exist (no -1 ambiguity).
# R38: -1 (dst unchanged) if its scratch cannot be allocated.

prakriya nighantu_kunjika_ashtak(m, out) {
    vitti cap = m[0]
    vitti i = 0
    vitti wpos = 0
    vitti n = 0
    vitti kl = 0
    vitti base = 0
    vitti k = 0
    yavat (i < cap) {
        yadi (m[2 + i] == 1) {
            kl = m[2 + cap + i]
            base = (2 + 3 * cap) * 8 + i * 32
            akshar_rakh(out, wpos, kl)
            k = 0
            yavat (k < kl) {
                akshar_rakh(out, wpos + 1 + k, akshar(m, base + k))
                k = k + 1
            }
            wpos = wpos + 1 + kl
            n = n + 1
        }
        i = i + 1
    }
    nivartanam n
}

prakriya patra_path_sarv(path, out, cap) {
    vitti p = path
    vitti dst = out
    vitti c = cap
    vitti fd = 0
    vitti total = 0
    yadi (c < 0) { nivartanam 0 - 1 }
    fd = dvaram(p, 0)
    yadi (fd < 0) { nivartanam 0 - 1 }
    yavat (total < c) {
        vitti n = paadh(fd, dst + total, c - total)
        yadi (n < 0) {
            band(fd)
            nivartanam 0 - 1
        }
        yadi (n == 0) {
            band(fd)
            nivartanam total
        }
        total = total + n
    }
    band(fd)
    nivartanam total
}

# patra_likh_sarv(path, data, n) — create/truncate path, write all n
# bytes from data, close. Returns n (0 for n == 0 on a creatable
# path), -1 on any error. n < 0 returns -1 without opening.

prakriya patra_likh_sarv(path, data, n) {
    vitti p = path
    vitti src = data
    vitti c = n
    vitti fd = 0
    vitti total = 0
    yadi (c < 0) { nivartanam 0 - 1 }
    fd = dvaram(p, 577)
    yadi (fd < 0) { nivartanam 0 - 1 }
    yavat (total < c) {
        vitti w = likha(fd, src + total, c - total)
        yadi (w <= 0) {
            band(fd)
            nivartanam 0 - 1
        }
        total = total + w
    }
    band(fd)
    nivartanam total
}

# patra_asti(path) — 1 if path opens read-only, 0 otherwise.
# (Open failure covers missing file, missing directory, and
# permission denial alike — the caller cannot distinguish them.)

prakriya patra_asti(path) {
    vitti fd = dvaram(path, 0)
    yadi (fd < 0) { nivartanam 0 }
    band(fd)
    nivartanam 1
}

prakriya phal_asti_siddhi(r) {
    nivartanam r[0]
}

# phal_mulya(r) — the value of a success Result. Caller must
# check phal_asti_siddhi first: on a failure Result this returns 0,
# which is indistinguishable from a success value of 0.

prakriya phal_mulya(r) {
    nivartanam r[1]
}

# phal_mulya_va(r, def) — the value if r is success, else def.
# The one-expression way to handle both branches.

prakriya phal_mulya_va(r, def) {
    yadi (r[0] == 1) { nivartanam r[1] }
    nivartanam def
}

# phal_se_siddhi(out, v, ok) — lift the ok convention into a
# Result: writes [ok[0], v] into out (value 0 on failure).

prakriya phal_se_siddhi(out, v, ok) {
    vitti o = out
    yadi (ok[0] == 1) {
        o[0] = 1
        o[1] = v
    } anya {
        o[0] = 0
        o[1] = 0
    }
    nivartanam o[0]
}

# phal_janchit_yuj/sub/mul/div/shesh(out, a, b) — the ganita
# checked operation, producing a Result in out instead of an
# ok out-parameter. On overflow (or div/shesh by zero, MIN/-1)
# the Result is failure [0, 0].

prakriya phal_janchit_yuj(out, a, b) {
    # out doubles as the ok cell: the ganita checked form writes
    # out[0] = ok flag and returns the value. No allocation, so
    # this module stays core.
    vitti o = out
    vitti v = ganita_janchit_yuj(a, b, o)
    yadi (o[0] == 1) {
        o[1] = v
    } anya {
        o[1] = 0
    }
    nivartanam o[0]
}

# phal_janchit_nyun(out, a, b) — checked subtraction: out[0] = ok flag, out[1] = a - b if ok else 0; returns out[0].

prakriya phal_janchit_nyun(out, a, b) {
    # out doubles as the ok cell: the ganita checked form writes
    # out[0] = ok flag and returns the value. No allocation, so
    # this module stays core.
    vitti o = out
    vitti v = ganita_janchit_nyun(a, b, o)
    yadi (o[0] == 1) {
        o[1] = v
    } anya {
        o[1] = 0
    }
    nivartanam o[0]
}

# phal_janchit_gun(out, a, b) — checked multiplication: out[0] = ok flag, out[1] = a * b if ok else 0; returns out[0].

prakriya phal_janchit_gun(out, a, b) {
    # out doubles as the ok cell: the ganita checked form writes
    # out[0] = ok flag and returns the value. No allocation, so
    # this module stays core.
    vitti o = out
    vitti v = ganita_janchit_gun(a, b, o)
    yadi (o[0] == 1) {
        o[1] = v
    } anya {
        o[1] = 0
    }
    nivartanam o[0]
}

# phal_janchit_bhaj(out, a, b) — checked division: out[0] = ok flag, out[1] = a / b if ok else 0; returns out[0].

prakriya phal_janchit_bhaj(out, a, b) {
    # out doubles as the ok cell: the ganita checked form writes
    # out[0] = ok flag and returns the value. No allocation, so
    # this module stays core.
    vitti o = out
    vitti v = ganita_janchit_bhaj(a, b, o)
    yadi (o[0] == 1) {
        o[1] = v
    } anya {
        o[1] = 0
    }
    nivartanam o[0]
}

# phal_janchit_shesh(out, a, b) — checked remainder: out[0] = ok flag, out[1] = a % b if ok else 0; returns out[0].

prakriya phal_janchit_shesh(out, a, b) {
    # out doubles as the ok cell: the ganita checked form writes
    # out[0] = ok flag and returns the value. No allocation, so
    # this module stays core.
    vitti o = out
    vitti v = ganita_janchit_shesh(a, b, o)
    yadi (o[0] == 1) {
        o[1] = v
    } anya {
        o[1] = 0
    }
    nivartanam o[0]
}

# phal_janchit_ghat(out, a, e) — ganita_janchit_ghat as a Result.
# Failure [0, 0] on e < 0 or overflow (see ganita_janchit_ghat).

prakriya phal_janchit_ghat(out, a, e) {
    vitti o = out
    vitti v = ganita_janchit_ghat(a, e, o)
    yadi (o[0] == 1) {
        o[1] = v
    } anya {
        o[1] = 0
    }
    nivartanam o[0]
}

# phal_janchit_kramgun(out, n) — ganita_janchit_kramgun as a Result.
# Failure [0, 0] on n < 0 or overflow (21! overflows).

prakriya phal_janchit_kramgun(out, n) {
    vitti o = out
    vitti v = ganita_janchit_kramgun(n, o)
    yadi (o[0] == 1) {
        o[1] = v
    } anya {
        o[1] = 0
    }
    nivartanam o[0]
}

# phal_janchit_nirapeksh(out, a) — ganita_janchit_nirapeksh as a Result.
# Failure [0, 0] on abs(MIN) (no int64 absolute value).

prakriya phal_janchit_nirapeksh(out, a) {
    vitti o = out
    vitti v = ganita_janchit_nirapeksh(a, o)
    yadi (o[0] == 1) {
        o[1] = v
    } anya {
        o[1] = 0
    }
    nivartanam o[0]
}

prakriya roop_ank(v, out) {
    vitti val = v
    vitti dst = out
    vitti rev = nirmmita(22 * 8)
    yadi (rev == 0) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    vitti rlen = 0
    vitti i = 0
    yadi (val == 0) {
        akshar_rakh(dst, 0, 48)
        akshar_rakh(dst, 1, 0)
        nivartanam 1
    }
    yadi (val < 0) {
        yadi (val == (0 - 9223372036854775807) - 1) {
            # |MIN| = 2^63 does not fit in int64; roop_ank_aadhar
            # handles it (hi/lo split), so delegate for this one value.
            nivartanam roop_ank_aadhar(val, 10, 0, dst)
        }
        val = 0 - val
    }
    yavat (val > 0) {
        rev[rlen] = (val % 10) + 48
        rlen = rlen + 1
        val = val / 10
    }
    i = 0
    yavat (i < rlen) {
        akshar_rakh(dst, i, rev[rlen - 1 - i])
        i = i + 1
    }
    akshar_rakh(dst, rlen, 0)
    nivartanam rlen
}

# --- integer digits in a base (private helper) ---
# roop_ank_aadhar(v, base, upper, out) — write |v| in `base` (2..36)
# into out as packed bytes, no util_chinha, no prefix. `upper` 1 -> A-F/A-Z.
# Base outside 2..36 writes only the terminator and returns 0.

prakriya roop_ank_aadhar(v, base, upper, out) {
    vitti val = v
    vitti b = base
    vitti up = upper
    vitti dst = out
    vitti rev = nirmmita(70 * 8)
    yadi (rev == 0) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    vitti rlen = 0
    vitti i = 0
    vitti d = 0
    vitti ch = 0
    yadi (b < 2) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    yadi (b > 36) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    yadi (val == 0) {
        akshar_rakh(dst, 0, 48)
        akshar_rakh(dst, 1, 0)
        nivartanam 1
    }
    yadi (val < 0) {
        yadi (val == (0 - 9223372036854775807) - 1) {
            # |MIN| = 2^63 does not fit in int64. Split it: |MIN| =
            # hi * b + lo with hi = -(MIN / b), lo = -(MIN % b),
            # both fitting. Convert hi, then append the lo digit.
            vitti hi = 0 - (val / b)
            vitti lo = 0 - (val % b)
            vitti hn = roop_ank_aadhar(hi, b, up, dst)
            yadi (lo < 10) {
                akshar_rakh(dst, hn, lo + 48)
            } anya {
                yadi (up == 1) {
                    akshar_rakh(dst, hn, lo + 55)
                } anya {
                    akshar_rakh(dst, hn, lo + 87)
                }
            }
            akshar_rakh(dst, hn + 1, 0)
            nivartanam hn + 1
        }
        val = 0 - val
    }
    yavat (val > 0) {
        d = val % b
        yadi (d < 10) {
            ch = d + 48
        } anya {
            yadi (up == 1) {
                ch = d + 55
            } anya {
                ch = d + 87
            }
        }
        rev[rlen] = ch
        rlen = rlen + 1
        val = val / b
    }
    i = 0
    yavat (i < rlen) {
        akshar_rakh(dst, i, rev[rlen - 1 - i])
        i = i + 1
    }
    akshar_rakh(dst, rlen, 0)
    nivartanam rlen
}

# roop_ank_aadhar2(v, base, out) — write v in `base` (2..36), lowercase
# digits, '-' for negatives, no prefix. Returns the byte count.
# Base outside 2..36: terminator only, returns 0. Digits are written
# directly at dst + neg, so the util_chinha just fills position 0.

prakriya roop_ank_aadhar2(v, base, out) {
    vitti val = v
    vitti dst = out
    vitti neg = 0
    vitti n = 0
    yadi (val < 0) {
        neg = 1
        val = 0 - val
    }
    n = roop_ank_aadhar(val, base, 0, dst + neg)
    yadi (n == 0) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    yadi (neg == 1) {
        akshar_rakh(dst, 0, 45)
    }
    nivartanam n + neg
}

# roop_ank_dhvaj(v, base, flags, out) — roop_ank_aadhar2 plus flags:
# bit 0 (1) = prefix: "0b" / "0o" / "0x" for bases 2 / 8 / 16
# (no prefix for other bases, including 10); bit 1 (2) = uppercase
# hex digits (the prefix itself stays lowercase). Returns byte count.

prakriya roop_ank_dhvaj(v, base, flags, out) {
    vitti val = v
    vitti b = base
    vitti fl = flags
    vitti dst = out
    vitti neg = 0
    vitti pre = 0
    vitti up = 0
    vitti n = 0
    vitti i = 0
    yadi (val < 0) {
        neg = 1
        val = 0 - val
    }
    yadi (fl % 2 == 1) {
        yadi (b == 2) { pre = 2 }
        yadi (b == 8) { pre = 2 }
        yadi (b == 16) { pre = 2 }
    }
    yadi ((fl / 2) % 2 == 1) { up = 1 }
    n = roop_ank_aadhar(val, b, up, dst + neg + pre)
    yadi (n == 0) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    # digits already sit at [neg+pre, ...); fill in util_chinha + prefix.
    yadi (neg == 1) { akshar_rakh(dst, 0, 45) }
    yadi (pre == 2) {
        akshar_rakh(dst, neg, 48)
        yadi (b == 2) { akshar_rakh(dst, neg + 1, 98) }
        yadi (b == 8) { akshar_rakh(dst, neg + 1, 111) }
        yadi (b == 16) { akshar_rakh(dst, neg + 1, 120) }
    }
    nivartanam neg + pre + n
}

# roop_dash(v, out) — decimal, no prefix. roop_shodash / roop_shodash_unnat /
# roop_asht / roop_dwi — base 16 (lower / upper), 8, 2, no prefix.

prakriya roop_dash(v, out) {
    nivartanam roop_ank_aadhar2(v, 10, out)
}

# roop_shodash(v, out) — formats v as lowercase hexadecimal into out (no prefix); returns the digit count.

prakriya roop_shodash(v, out) {
    nivartanam roop_ank_aadhar2(v, 16, out)
}

# roop_shodash_unnat(v, out) — formats v as UPPERCASE hexadecimal into out (no prefix); returns the digit count.

prakriya roop_shodash_unnat(v, out) {
    nivartanam roop_ank_dhvaj(v, 16, 2, out)
}

# roop_asht(v, out) — formats v as octal into out (no prefix); returns the digit count.

prakriya roop_asht(v, out) {
    nivartanam roop_ank_aadhar2(v, 8, out)
}

# roop_dwi(v, out) — formats v as binary into out (no prefix); returns the digit count.

prakriya roop_dwi(v, out) {
    nivartanam roop_ank_aadhar2(v, 2, out)
}

# roop_ank_pre(v, base, upper, out) — any base with its prefix
# ("0b"/"0o"/"0x" for 2/8/16; none for other bases). `upper` 1 ->
# uppercase digits, prefix stays lowercase.

prakriya roop_ank_pre(v, base, upper, out) {
    vitti fl = 1
    yadi (upper == 1) { fl = 3 }
    nivartanam roop_ank_dhvaj(v, base, fl, out)
}

# --- padding / alignment ---
# roop_pad_vam(src, sn, width, padbyte, out) — pad on the LEFT with
# `padbyte` (32 space, 48 '0') to `width`. width <= sn: copy unchanged.

prakriya roop_pad_vam(src, sn, width, padbyte, out) {
    vitti s = src
    vitti cnt = sn
    vitti w = width
    vitti f = padbyte
    vitti dst = out
    vitti npad = 0
    vitti i = 0
    yadi (w <= cnt) {
        i = 0
        yavat (i < cnt) {
            akshar_rakh(dst, i, akshar(s, i))
            i = i + 1
        }
        akshar_rakh(dst, cnt, 0)
        nivartanam cnt
    }
    npad = w - cnt
    i = 0
    yavat (i < npad) {
        akshar_rakh(dst, i, f)
        i = i + 1
    }
    i = 0
    yavat (i < cnt) {
        akshar_rakh(dst, npad + i, akshar(s, i))
        i = i + 1
    }
    akshar_rakh(dst, w, 0)
    nivartanam w
}

# roop_pad_dakshin(src, sn, width, padbyte, out) — pad on the RIGHT.

prakriya roop_pad_dakshin(src, sn, width, padbyte, out) {
    vitti s = src
    vitti cnt = sn
    vitti w = width
    vitti f = padbyte
    vitti dst = out
    vitti npad = 0
    vitti i = 0
    yadi (w <= cnt) {
        i = 0
        yavat (i < cnt) {
            akshar_rakh(dst, i, akshar(s, i))
            i = i + 1
        }
        akshar_rakh(dst, cnt, 0)
        nivartanam cnt
    }
    npad = w - cnt
    i = 0
    yavat (i < cnt) {
        akshar_rakh(dst, i, akshar(s, i))
        i = i + 1
    }
    i = 0
    yavat (i < npad) {
        akshar_rakh(dst, cnt + i, f)
        i = i + 1
    }
    akshar_rakh(dst, w, 0)
    nivartanam w
}

# roop_pad_madhya(src, sn, width, padbyte, out) — pad both sides to width;
# when width-sn is odd, the extra padding byte goes RIGHT.

prakriya roop_varg_mool(src, sn, step, out) {
    vitti s = src
    vitti cnt = sn
    vitti st = step
    vitti dst = out
    vitti start = 0
    vitti dot = 0
    vitti wpos = 0
    vitti i = 0
    vitti k = 0
    vitti rem = 0
    yadi (cnt == 0) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    yadi (akshar(s, 0) == 45) { start = 1 }
    yadi (akshar(s, 0) == 43) { start = 1 }
    dot = cnt
    i = start
    yavat (i < cnt) {
        yadi (akshar(s, i) == 46) {
            dot = i
            i = cnt
        } anya {
            i = i + 1
        }
    }
    # copy the util_chinha, if any
    yadi (start == 1) {
        akshar_rakh(dst, 0, akshar(s, 0))
        wpos = 1
    }
    # emit the integer part with ',' separators. A comma goes after
    # digit i iff rem (digits after i) marks a group boundary:
    # international: rem % 3 == 0; Indian: rem == 3, or rem > 3 with
    # (rem - 3) % 2 == 0 (rightmost group is 3, then 2s).
    i = start
    yavat (i < dot) {
        akshar_rakh(dst, wpos, akshar(s, i))
        wpos = wpos + 1
        rem = dot - i - 1
        yadi (rem > 0) {
            yadi (st == 3) {
                yadi (rem % 3 == 0) {
                    akshar_rakh(dst, wpos, 44)
                    wpos = wpos + 1
                }
            } anya {
                yadi (rem == 3) {
                    akshar_rakh(dst, wpos, 44)
                    wpos = wpos + 1
                } anya {
                    yadi (rem > 3) {
                        yadi ((rem - 3) % 2 == 0) {
                            akshar_rakh(dst, wpos, 44)
                            wpos = wpos + 1
                        }
                    }
                }
            }
        }
        i = i + 1
    }
    # copy the fraction (including the '.') verbatim
    k = dot
    yavat (k < cnt) {
        akshar_rakh(dst, wpos, akshar(s, k))
        wpos = wpos + 1
        k = k + 1
    }
    akshar_rakh(dst, wpos, 0)
    nivartanam wpos
}

# roop_varg_bharatiya(src, sn, out) — 1234567 -> 12,34,567.

prakriya roop_varg_bharatiya(src, sn, out) {
    nivartanam roop_varg_mool(src, sn, 2, out)
}

# roop_varg_vishwa(src, sn, out) — 1234567 -> 1,234,567.

prakriya roop_varg_vishwa(src, sn, out) {
    nivartanam roop_varg_mool(src, sn, 3, out)
}

# roop_varg(src, sn, out) — DEFAULT grouping: Indian (12,34,567).
# The default is Indian because the audience is Indian.

prakriya roop_varg(src, sn, out) {
    nivartanam roop_varg_bharatiya(src, sn, out)
}

# roop_varg_ank(v, indian, out) — format integer v, then group it.
# `indian` 1 -> Indian grouping, 0 -> international.

prakriya roop_varg_ank(v, indian, out) {
    vitti tmp = nirmmita(32)
    yadi (tmp == 0) {
        akshar_rakh(out, 0, 0)
        nivartanam 0
    }
    vitti n = roop_ank_aadhar2(v, 10, tmp)
    yadi (n == 0) {
        akshar_rakh(out, 0, 0)
        nivartanam 0
    }
    yadi (indian == 1) {
        nivartanam roop_varg_bharatiya(tmp, n, out)
    }
    nivartanam roop_varg_vishwa(tmp, n, out)
}

# --- fixed decimals (private helper) ---
# roop_sthir_mool(dasham x, places, always_sign, out) — |x| rounded HALF AWAY
# FROM ZERO to `places` digits after '.', exactly `places` digits
# emitted (zero-padded). places clamped to 0..9. `always_sign` 1 emits
# '+' for non-negative values. places 0 emits no '.'.

prakriya roop_sthir_mool(dasham x, places, always_sign, out) {
    dasham v = x
    vitti pl = places
    vitti asign = always_sign
    vitti dst = out
    dasham p10f = 1.0
    vitti p10i = 1
    vitti i = 0
    vitti neg = 0
    dasham mag = 0.0
    dasham scaled = 0.0
    vitti rounded = 0
    vitti intpart = 0
    vitti fracpart = 0
    vitti wpos = 0
    vitti ndig = 0
    vitti rev = nirmmita(22 * 8)
    yadi (rev == 0) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    vitti rlen = 0
    vitti k = 0
    yadi (pl < 0) { pl = 0 }
    yadi (pl > 9) { pl = 9 }
    yavat (i < pl) {
        p10f = p10f * 10.0
        p10i = p10i * 10
        i = i + 1
    }
    yadi (v < 0.0) {
        neg = 1
        mag = 0.0 - v
    } anya {
        mag = v
    }
    # NaN guard: NaN is the only value with both v == 0.0 and
    # v < 0.0 true (this language's dasham comparisons use
    # ucomisd flags directly, so NaN == NaN is true and
    # NaN != NaN is false — v != v does NOT detect NaN here).
    # Without it, NaN took the neg branch (NaN < 0 is true) and
    # the conversion produced garbage like "-9223372036...".
    yadi (v == 0.0) {
        yadi (v < 0.0) {
            akshar_rakh(dst, 0, 0)
            nivartanam 0
        }
    }
    scaled = mag * p10f + 0.5
    # Overflow guard: if scaled >= 2^63 the dasham->int conversion
    # below is indefinite (x86 cvttsd2si yields MIN) and the
    # program segfaults downstream. Return 0 with empty output
    # instead — |x| * 10^places must fit in int64.
    # NOTE: written as 9223372036854775807.0 (MAX) because the
    # literal 9223372036854775808.0 overflows the int64 part of
    # the dasham parser; as a dvigun, MAX.0 rounds to 2^63, so
    # this is exactly the cvttsd2si indefinite boundary.
    yadi (scaled >= 9223372036854775807.0) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    rounded = scaled
    intpart = rounded / p10i
    fracpart = rounded % p10i
    # util_chinha
    yadi (neg == 1) {
        akshar_rakh(dst, 0, 45)
        wpos = 1
    } anya {
        yadi (asign == 1) {
            akshar_rakh(dst, 0, 43)
            wpos = 1
        }
    }
    # integer part
    ndig = roop_ank(intpart, dst + wpos)
    yadi (ndig == 0) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    wpos = wpos + ndig
    # fraction part, zero-padded to exactly pl digits
    yadi (pl > 0) {
        akshar_rakh(dst, wpos, 46)
        wpos = wpos + 1
        rlen = 0
        yadi (fracpart == 0) {
            rev[0] = 48
            rlen = 1
        } anya {
            yavat (fracpart > 0) {
                rev[rlen] = (fracpart % 10) + 48
                rlen = rlen + 1
                fracpart = fracpart / 10
            }
        }
        k = 0
        yavat (k < pl - rlen) {
            akshar_rakh(dst, wpos, 48)
            wpos = wpos + 1
            k = k + 1
        }
        k = 0
        yavat (k < rlen) {
            akshar_rakh(dst, wpos, rev[rlen - 1 - k])
            wpos = wpos + 1
            k = k + 1
        }
    }
    akshar_rakh(dst, wpos, 0)
    nivartanam wpos
}

# roop_sthir(dasham x, places, out) — fixed decimals, '-' for negatives only.
# 3.14159 at 2 places -> "3.14". Rounding: half away from zero.

prakriya roop_sthir(dasham x, places, out) {
    nivartanam roop_sthir_mool(x, places, 0, out)
}

# roop_sthir_chinhit(dasham x, places, out) — fixed decimals, always a util_chinha:
# "+3.14" / "-3.14".

prakriya roop_sthir_chinhit(dasham x, places, out) {
    nivartanam roop_sthir_mool(x, places, 1, out)
}

# --- signed formatting ---
# roop_chinhit(v, out) — always a util_chinha: "+42" / "-42" / "+0".

prakriya roop_chinhit(v, out) {
    vitti val = v
    vitti dst = out
    vitti tmp = nirmmita(32)
    vitti n = 0
    vitti i = 0
    yadi (tmp == 0) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    n = roop_ank_aadhar2(val, 10, tmp)
    yadi (n == 0) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    yadi (val < 0) {
        i = 0
        yavat (i < n) {
            akshar_rakh(dst, i, akshar(tmp, i))
            i = i + 1
        }
        akshar_rakh(dst, n, 0)
        nivartanam n
    }
    akshar_rakh(dst, 0, 43)
    i = 0
    yavat (i < n) {
        akshar_rakh(dst, i + 1, akshar(tmp, i))
        i = i + 1
    }
    akshar_rakh(dst, n + 1, 0)
    nivartanam n + 1
}

# roop_sign_akshar(v, signch, out) — `signch` (a byte value, e.g. 32 for a
# blank, 43 for '+') in place of '+' for non-negative values; negatives
# always get '-'.

prakriya roop_sign_akshar(v, signch, out) {
    vitti val = v
    vitti sc = signch
    vitti dst = out
    vitti tmp = nirmmita(32)
    vitti n = 0
    vitti i = 0
    yadi (tmp == 0) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    n = roop_ank_aadhar2(val, 10, tmp)
    yadi (n == 0) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    yadi (val < 0) {
        i = 0
        yavat (i < n) {
            akshar_rakh(dst, i, akshar(tmp, i))
            i = i + 1
        }
        akshar_rakh(dst, n, 0)
        nivartanam n
    }
    akshar_rakh(dst, 0, sc)
    i = 0
    yavat (i < n) {
        akshar_rakh(dst, i + 1, akshar(tmp, i))
        i = i + 1
    }
    akshar_rakh(dst, n + 1, 0)
    nivartanam n + 1
}

prakriya yog_seema(start, end) {
    yadi (end < start) { nivartanam 0 }
    nivartanam (start + end) * (end - start + 1) / 2
}

# shesh(a, b) — remainder a % b computed as a - (a / b) * b; 0 if b == 0.

prakriya shesh(a, b) {
    yadi (b == 0) { nivartanam 0 }
    nivartanam a - (a / b) * b
}

# bhaj_urdhva(a, b) — ceiling division of a by b (rounds up when the remainder is nonzero); 0 if b == 0.

prakriya bhaj_urdhva(a, b) {
    # Ceiling division: q = a / b (truncating), round up iff the
    # remainder is nonzero and has the divisor's util_chinha. The old
    # (a + b - 1) / b was only correct for a >= 0, b > 0.
    yadi (b == 0) { nivartanam 0 }
    vitti q = a / b
    vitti r = a % b
    yadi (r != 0) {
        yadi (r > 0) {
            yadi (b > 0) { q = q + 1 }
        } anya {
            yadi (b < 0) { q = q + 1 }
        }
    }
    nivartanam q
}

# util_chinha(n) — sign of n: 1 if n > 0, -1 if n < 0, 0 if n == 0.

prakriya samanvaya_akar_na(m, n, len) {
    yadi (m < 0) { nivartanam 1 }
    yadi (n < 0) { nivartanam 1 }
    yadi (n == 0) { nivartanam 0 }
    yadi (m > len / n) { nivartanam 1 }
    nivartanam 0
}

# identity matrix: n x n, out must hold n*n elements

prakriya pehchan(n, kosh dasham out) {
    vitti i = 0
    yavat (i < n) {
        vitti j = 0
        yavat (j < n) {
            yadi (i == j) {
                out[i * n + j] = 1.0
            } anya {
                out[i * n + j] = 0.0
            }
            j = j + 1
        }
        i = i + 1
    }
    nivartanam n * n
}

# transpose: a is m x n, out must hold n*m elements

prakriya vivartana(kosh dasham a, m, n, kosh dasham out) {
    vitti i = 0
    yavat (i < m) {
        vitti j = 0
        yavat (j < n) {
            out[j * m + i] = a[i * n + j]
            j = j + 1
        }
        i = i + 1
    }
    nivartanam m * n
}

# element-wise sum: a and b are m x n, out must hold m*n elements.
# R37: -1 if m x n does not fit a, b and out (or m, n < 0); m * n is never
# formed until it is known to fit, so it cannot wrap to a small loop.

prakriya matrika_yoga(kosh dasham a, kosh dasham b, m, n, kosh dasham out) {
    vitti k = 0
    yadi (samanvaya_akar_na(m, n, kosh_len(a)) == 1) { nivartanam 0 - 1 }
    yadi (samanvaya_akar_na(m, n, kosh_len(b)) == 1) { nivartanam 0 - 1 }
    yadi (samanvaya_akar_na(m, n, kosh_len(out)) == 1) { nivartanam 0 - 1 }
    yavat (k < m * n) {
        out[k] = a[k] + b[k]
        k = k + 1
    }
    nivartanam m * n
}

# scalar multiple: out must hold m*n elements. R37: -1 if m x n does not fit.

prakriya skalar(kosh dasham a, dasham c, m, n, kosh dasham out) {
    vitti k = 0
    yadi (samanvaya_akar_na(m, n, kosh_len(a)) == 1) { nivartanam 0 - 1 }
    yadi (samanvaya_akar_na(m, n, kosh_len(out)) == 1) { nivartanam 0 - 1 }
    yavat (k < m * n) {
        out[k] = a[k] * c
        k = k + 1
    }
    nivartanam m * n
}

# matrix product: a is m x n, b is n x p, out must hold m*p elements

prakriya matrika_gunana(kosh dasham a, kosh dasham b, m, n, p, kosh dasham out) {
    vitti i = 0
    yavat (i < m) {
        vitti j = 0
        yavat (j < p) {
            dasham acc = 0.0
            vitti k = 0
            yavat (k < n) {
                acc = acc + a[i * n + k] * b[k * p + j]
                k = k + 1
            }
            out[i * p + j] = acc
            j = j + 1
        }
        i = i + 1
    }
    nivartanam m * p
}

# trace of an n x n matrix

prakriya nishan(kosh dasham a, n) {
    dasham t = 0.0
    vitti i = 0
    yavat (i < n) {
        t = t + a[i * n + i]
        i = i + 1
    }
    nivartanam t
}

# determinant of a 2 x 2 matrix (a holds 4 elements)

prakriya nirnaya2(kosh dasham a) {
    nivartanam a[0] * a[3] - a[1] * a[2]
}

# determinant of a 3 x 3 matrix (a holds 9 elements), by cofactor expansion

prakriya sadish_yoga(kosh dasham u, kosh dasham v) {
    vitti n = kosh_len(u)
    yadi (kosh_len(v) < n) { n = kosh_len(v) }
    dasham s = 0.0
    vitti i = 0
    yavat (i < n) {
        s = s + u[i] * v[i]
        i = i + 1
    }
    nivartanam s
}

# largest absolute row sum (a cheap norm, useful for conditioning checks)

prakriya rekha_manak(kosh dasham a, m, n) {
    dasham best = 0.0
    vitti i = 0
    yavat (i < m) {
        dasham row = 0.0
        vitti j = 0
        yavat (j < n) {
            dasham e = a[i * n + j]
            yadi (e < 0.0) { e = 0.0 - e }
            row = row + e
            j = j + 1
        }
        yadi (row > best) { best = row }
        i = i + 1
    }
    nivartanam best
}

prakriya rakh_srij(cap) {
    nivartanam nighantu_srij(cap)
}

# rakh_yuj(s, cap, elem, elem_n) — add elem; 1 on success, 0 if the set
# is full (then the set is unchanged). Adding an existing element keeps
# rakh_maap unchanged (idempotent).

prakriya rakh_yuj(s, cap, elem, elem_n) {
    nivartanam nighantu_khip(s, cap, elem, elem_n, 1)
}

# rakh_antah(s, cap, elem, elem_n) — 1 if elem is in the set, else 0.

prakriya rakh_antah(s, cap, elem, elem_n) {
    nivartanam nighantu_antah(s, cap, elem, elem_n)
}

# rakh_apanay(s, cap, elem, elem_n) — remove elem; 1 if removed, 0 if absent.

prakriya rakh_apanay(s, cap, elem, elem_n) {
    nivartanam nighantu_apanay(s, cap, elem, elem_n)
}

# rakh_maap(s) — number of elements.

prakriya rakh_samroop_diff(a, cap, b, bcap, out) {
    vitti ocap = out[0]
    vitti tmpa = nirmmita(a[0] * 33 + 1)
    vitti tmpb = nirmmita(b[0] * 33 + 1)
    yadi (tmpa == 0 || tmpb == 0) { nivartanam 0 - 1 }
    vitti nka = nighantu_kunjika_ashtak(a, tmpa)
    vitti nkb = nighantu_kunjika_ashtak(b, tmpb)
    vitti pos = 0
    vitti i = 0
    vitti seglen = 0
    yavat (i < nka) {
        seglen = akshar(tmpa, pos)
        yadi (nighantu_antah(b, bcap, tmpa + pos + 1, seglen) == 0) {
            nighantu_khip(out, ocap, tmpa + pos + 1, seglen, 1)
        }
        pos = pos + 1 + seglen
        i = i + 1
    }
    pos = 0
    i = 0
    yavat (i < nkb) {
        seglen = akshar(tmpb, pos)
        yadi (nighantu_antah(a, cap, tmpb + pos + 1, seglen) == 0) {
            nighantu_khip(out, ocap, tmpb + pos + 1, seglen, 1)
        }
        pos = pos + 1 + seglen
        i = i + 1
    }
    nivartanam nighantu_maap(out)
}

# rakh_sangam(a, cap, b, bcap, out) — add every element of a and of b into
# out (fresh, empty, capacity >= cap + bcap). Returns rakh_maap(out).

prakriya rakh_sampat(a, cap, b, bcap, out) {
    vitti ocap = out[0]
    vitti tmpa = nirmmita(a[0] * 33 + 1)
    yadi (tmpa == 0) { nivartanam 0 - 1 }
    vitti nka = nighantu_kunjika_ashtak(a, tmpa)
    vitti pos = 0
    vitti i = 0
    vitti seglen = 0
    yavat (i < nka) {
        seglen = akshar(tmpa, pos)
        yadi (nighantu_antah(b, bcap, tmpa + pos + 1, seglen) == 1) {
            nighantu_khip(out, ocap, tmpa + pos + 1, seglen, 1)
        }
        pos = pos + 1 + seglen
        i = i + 1
    }
    nivartanam nighantu_maap(out)
}

# rakh_bhed(a, cap, b, bcap, out) — add every element of a that is
# NOT in b into out (fresh, empty, capacity >= cap). Returns
# rakh_maap(out).

prakriya rakh_bhed(a, cap, b, bcap, out) {
    vitti ocap = out[0]
    vitti tmpa = nirmmita(a[0] * 33 + 1)
    yadi (tmpa == 0) { nivartanam 0 - 1 }
    vitti nka = nighantu_kunjika_ashtak(a, tmpa)
    vitti pos = 0
    vitti i = 0
    vitti seglen = 0
    yavat (i < nka) {
        seglen = akshar(tmpa, pos)
        yadi (nighantu_antah(b, bcap, tmpa + pos + 1, seglen) == 0) {
            nighantu_khip(out, ocap, tmpa + pos + 1, seglen, 1)
        }
        pos = pos + 1 + seglen
        i = i + 1
    }
    nivartanam nighantu_maap(out)
}

# rakh_vardh(s, newcap) — copy the set into a fresh set of capacity
# newcap (WS2, R20). A set IS a map, so this is nighantu_vardh's copy
# with the same all-or-nothing rule: returns the new handle, or 0
# if newcap < rakh_maap(s). Rebind: s = rakh_vardh(s, 32).

prakriya rakh_rikta(s) {
    nivartanam nighantu_rikta(s)
}

# rakh_sam(a, cap, b, bcap) — 1 if a and b hold exactly the same
# elements, else 0 (WS3, R19). Both subset checks in one call;
# two empty sets are equal.

prakriya rakh_sam(a, cap, b, bcap) {
    vitti r = rakh_asti_upasamuh(a, cap, b, bcap)
    yadi (r != 1) { nivartanam r }
    nivartanam rakh_asti_upasamuh(b, bcap, a, cap)
}

# rakh_asti_upasamuh(a, cap, b, bcap) — 1 if every element of a is in b, else
# 0. Empty a is a subset of everything.

prakriya rakh_asti_upasamuh(a, cap, b, bcap) {
    vitti tmpa = nirmmita(a[0] * 33 + 1)
    yadi (tmpa == 0) { nivartanam 0 - 1 }
    vitti nka = nighantu_kunjika_ashtak(a, tmpa)
    vitti pos = 0
    vitti i = 0
    vitti seglen = 0
    yavat (i < nka) {
        seglen = akshar(tmpa, pos)
        yadi (nighantu_antah(b, bcap, tmpa + pos + 1, seglen) == 0) {
            nivartanam 0
        }
        pos = pos + 1 + seglen
        i = i + 1
    }
    nivartanam 1
}

# rakh_tak_mala(s, cap, out) — write the set's elements into out in
# length-prefixed form [len0, b0, b1, ..., len1, b0, ...] (same shape as
# nighantu_kunjika / khand_bhed parts), SORTED lexicographically by byte value
# (khand_tul), so output is deterministic regardless of insertion
# order or hash layout. Returns the element count.

prakriya yoga(kosh dasham xs) {
    dasham s = 0.0
    vitti i = 0
    yavat (i < kosh_len(xs)) {
        s = s + xs[i]
        i = i + 1
    }
    nivartanam s
}

# --- arithmetic mean ---

prakriya madhya(kosh dasham xs) {
    vitti n = kosh_len(xs)
    yadi (n == 0) { nivartanam 0.0 }
    nivartanam yoga(xs) / n
}

# --- minimum ---

prakriya laghutama(kosh dasham xs) {
    vitti n = kosh_len(xs)
    yadi (n == 0) { nivartanam 0.0 }
    dasham m = xs[0]
    vitti i = 1
    yavat (i < n) {
        yadi (xs[i] < m) { m = xs[i] }
        i = i + 1
    }
    nivartanam m
}

# --- maximum ---

prakriya adhikatama(kosh dasham xs) {
    vitti n = kosh_len(xs)
    yadi (n == 0) { nivartanam 0.0 }
    dasham m = xs[0]
    vitti i = 1
    yavat (i < n) {
        yadi (xs[i] > m) { m = xs[i] }
        i = i + 1
    }
    nivartanam m
}

# --- range (max - min) ---

prakriya vyapti(kosh dasham xs) {
    nivartanam adhikatama(xs) - laghutama(xs)
}

# --- population variance (प्रसरण) ---

prakriya prasaran(kosh dasham xs) {
    vitti n = kosh_len(xs)
    yadi (n == 0) { nivartanam 0.0 }
    dasham m = madhya(xs)
    dasham acc = 0.0
    vitti i = 0
    yavat (i < n) {
        dasham d = xs[i] - m
        acc = acc + d * d
        i = i + 1
    }
    nivartanam acc / n
}

# --- vargit root, Newton's method (private to this module: distinct name so it
#     never collides with madhava_vargmool or a user function) ---
# 1000 iterations, as madhava_vargmool (20 gave 1279996 for sqrt(1e12)).

prakriya sankhyiki_vargmool(dasham v) {
    yadi (v <= 0.0) { nivartanam 0.0 }
    dasham g = v
    vitti k = 0
    yavat (k < 1000) {
        g = (g + v / g) / 2.0
        k = k + 1
    }
    nivartanam g
}

# --- population standard deviation (मानक विचलन) ---

prakriya vichalan(kosh dasham xs) {
    nivartanam sankhyiki_vargmool(prasaran(xs))
}

# --- dot product of two float arrays (बिंदु गुणनफल) ---

prakriya bindu(kosh dasham a, kosh dasham b) {
    vitti na = kosh_len(a)
    vitti nb = kosh_len(b)
    vitti n = na
    yadi (nb < n) { n = nb }
    dasham s = 0.0
    vitti i = 0
    yavat (i < n) {
        s = s + a[i] * b[i]
        i = i + 1
    }
    nivartanam s
}

# --- Euclidean norm (magnitude) of a vector ---

prakriya purna_yoga(xs, n) {
    vitti i = 0
    vitti s = 0
    yavat (i < n) {
        s = s + xs[i]
        i = i + 1
    }
    nivartanam s
}

# --- integer mean (truncated toward zero) ---

prakriya purna_madhya(xs, n) {
    yadi (n <= 0) { nivartanam 0 }
    nivartanam purna_yoga(xs, n) / n
}

# --- integer minimum ---

prakriya purna_laghutama(xs, n) {
    vitti m = 0
    vitti i = 1
    yadi (n <= 0) { nivartanam 0 }
    m = xs[0]
    yavat (i < n) {
        yadi (xs[i] < m) { m = xs[i] }
        i = i + 1
    }
    nivartanam m
}

# --- integer maximum ---

prakriya purna_adhikatama(xs, n) {
    vitti m = 0
    vitti i = 1
    yadi (n <= 0) { nivartanam 0 }
    m = xs[0]
    yavat (i < n) {
        yadi (xs[i] > m) { m = xs[i] }
        i = i + 1
    }
    nivartanam m
}

# --- integer range (max - min) ---

prakriya purna_vyapti(xs, n) {
    yadi (n <= 0) { nivartanam 0 }
    nivartanam purna_adhikatama(xs, n) - purna_laghutama(xs, n)
}

# --- integer population variance (truncated toward zero; uses the
# truncated mean, so exact only when the mean is integral) ---

prakriya purna_prasaran(xs, n) {
    vitti m = 0
    vitti acc = 0
    vitti i = 0
    vitti d = 0
    yadi (n <= 0) { nivartanam 0 }
    m = purna_madhya(xs, n)
    yavat (i < n) {
        d = xs[i] - m
        acc = acc + d * d
        i = i + 1
    }
    nivartanam acc / n
}

prakriya vinimay(a, i, j) {
    vitti t = a[i]
    a[i] = a[j]
    a[j] = t
}

# budbud_shreni(a, n) — sorts a[0..n-1] in place, ascending, by bubble sort.

prakriya budbud_shreni(a, n) {
    vitti i = 0
    yavat (i < n) {
        vitti j = 0
        yavat (j < n - 1 - i) {
            yadi (a[j] > a[j + 1]) {
                vinimay(a, j, j + 1)
            }
            j = j + 1
        }
        i = i + 1
    }
}

# viparyay_mala(a, n) — reverses a[0..n-1] in place.

prakriya viparyay_mala(a, n) {
    vitti i = 0
    vitti j = n - 1
    yavat (i < j) {
        vinimay(a, i, j)
        i = i + 1
        j = j - 1
    }
}

# laghu(a, n) — smallest element of a[0..n-1]; 0 if n <= 0.

prakriya laghu(a, n) {
    # n <= 0: no element exists — return 0, as suchi_laghu does
    # on an empty list (the old code read a[0] and segfaulted).
    yadi (n <= 0) { nivartanam 0 }
    vitti i = 1
    vitti best = a[0]
    yavat (i < n) {
        yadi (a[i] < best) { best = a[i] }
        i = i + 1
    }
    nivartanam best
}

# adhik(a, n) — largest element of a[0..n-1]; 0 if n <= 0.

prakriya adhik(a, n) {
    # n <= 0: no element exists — return 0, as laghu.
    yadi (n <= 0) { nivartanam 0 }
    vitti i = 1
    vitti best = a[0]
    yavat (i < n) {
        yadi (a[i] > best) { best = a[i] }
        i = i + 1
    }
    nivartanam best
}

# yog(a, n) — sum of a[0..n-1].

prakriya yog(a, n) {
    vitti i = 0
    vitti s = 0
    yavat (i < n) {
        s = s + a[i]
        i = i + 1
    }
    nivartanam s
}

# anwesh_sarak(a, n, target) — index of the first occurrence of target in a[0..n-1], or -1.

prakriya anwesh_sarak(a, n, target) {
    vitti i = 0
    yavat (i < n) {
        yadi (a[i] == target) { nivartanam i }
        i = i + 1
    }
    nivartanam 0 - 1
}

# gan(a, n, target) — count of occurrences of target in a[0..n-1].

prakriya gan(a, n, target) {
    vitti i = 0
    vitti c = 0
    yavat (i < n) {
        yadi (a[i] == target) { c = c + 1 }
        i = i + 1
    }
    nivartanam c
}

# asti_sorted(a, n) — 1 if a[0..n-1] is in non-decreasing order, else 0.

prakriya asti_sorted(a, n) {
    vitti i = 0
    yavat (i < n - 1) {
        yadi (a[i] > a[i + 1]) { nivartanam 0 }
        i = i + 1
    }
    nivartanam 1
}

# dwi_anwesh(a, n, target) — binary search for target in sorted a[0..n-1]: its index, or -1.

prakriya dwi_anwesh(a, n, target) {
    vitti lo = 0
    vitti hi = n - 1
    yavat (lo <= hi) {
        vitti mid = (lo + hi) / 2
        yadi (a[mid] == target) { nivartanam mid }
        yadi (a[mid] < target) { lo = mid + 1 } anya { hi = mid - 1 }
    }
    nivartanam 0 - 1
}

# shankh_shreni(a, n) — sorts a[0..n-1] in place, ascending, by shell sort.

prakriya shankh_shreni(a, n) {
    vitti gap = n / 2
    yavat (gap > 0) {
        vitti i = gap
        yavat (i < n) {
            vitti temp = a[i]
            vitti j = i
            vitti go = 1
            yavat (go == 1) {
                yadi (j >= gap) {
                    yadi (a[j - gap] > temp) {
                        a[j] = a[j - gap]
                        j = j - gap
                    } anya {
                        go = 0
                    }
                } anya {
                    go = 0
                }
            }
            a[j] = temp
            i = i + 1
        }
        gap = gap / 2
    }
}

# nivesh_shreni(a, n) — sorts a[0..n-1] in place, ascending, by insertion sort.

prakriya nivesh_shreni(a, n) {
    vitti arr = a
    vitti len = n
    vitti i = 1
    yavat (i < len) {
        vitti key = arr[i]
        vitti j = i - 1
        vitti done = 0
        yavat (done == 0) {
            yadi (j < 0) {
                done = 1
            } anya {
                yadi (arr[j] > key) {
                    arr[j + 1] = arr[j]
                    j = j - 1
                } anya {
                    done = 1
                }
            }
        }
        arr[j + 1] = key
        i = i + 1
    }
}

# mil_shreni(a, n) — top-down merge sort using a temp buffer.

prakriya mil_shreni_punar(a, tmp, lo, hi) {
    yadi (hi - lo < 2) { nivartanam 0 }
    vitti mid = (lo + hi) / 2
    mil_shreni_punar(a, tmp, lo, mid)
    mil_shreni_punar(a, tmp, mid, hi)
    # merge a[lo:mid] and a[mid:hi] into tmp[lo:hi], copy back
    vitti i = lo
    vitti j = mid
    vitti k = lo
    vitti done = 0
    yavat (done == 0) {
        vitti iex = 0
        yadi (i >= mid) { iex = 1 }
        vitti jex = 0
        yadi (j >= hi) { jex = 1 }
        yadi (iex == 1) {
            yadi (jex == 1) {
                done = 1
            } anya {
                tmp[k] = a[j]
                j = j + 1
                k = k + 1
            }
        } anya {
            yadi (jex == 1) {
                tmp[k] = a[i]
                i = i + 1
                k = k + 1
            } anya {
                yadi (a[j] < a[i]) {
                    tmp[k] = a[j]
                    j = j + 1
                } anya {
                    tmp[k] = a[i]
                    i = i + 1
                }
                k = k + 1
            }
        }
    }
    vitti c = lo
    yavat (c < hi) {
        a[c] = tmp[c]
        c = c + 1
    }
    nivartanam 0
}

# mil_shreni(a, n) — merge sort; returns 0, or -1 (a unchanged) if its scratch cannot be allocated.

prakriya mil_shreni(a, n) {
    yadi (n < 2) { nivartanam 0 }
    yadi (n > 1152921504606846975) { nivartanam 0 - 1 }   # R39: n * 8 must not wrap
    vitti tmp = nirmmita(n * 8)
    yadi (tmp == 0 && n > 0) { nivartanam 0 - 1 }
    mil_shreni_punar(a, tmp, 0, n)
}

prakriya suchi_srij(cap) {
    vitti c = cap
    vitti l = 0
    vitti d = 0
    vitti sz = 0
    yadi (c < 1) { c = 1 }
    yadi (c > 1152921504606846975) { nivartanam 0 }   # R35: c * 8 must not wrap
    sz = c * 8
    yadi (sz < 0) { nivartanam 0 }
    l = nirmmita(3 * 8)
    yadi (l == 0) { nivartanam 0 }
    d = nirmmita(sz)
    yadi (d == 0) { nivartanam 0 }
    l[0] = 0
    l[1] = c
    l[2] = d
    nivartanam l
}

# suchi_vardh(l) — private helper: dvigun l's capacity, copying the
# data. Returns 1 ok / 0 allocation failure (list unchanged).

prakriya suchi_khip(l, v) {
    vitti lst = l
    vitti val = v
    yadi (lst[0] == lst[1]) {
        yadi (suchi_vardh(lst) == 0) { nivartanam 0 }
    }
    vitti d = lst[2]
    d[lst[0]] = val
    lst[0] = lst[0] + 1
    nivartanam 1
}

# suchi_grah(l, i) — element i, or 0 if i is out of bounds.

prakriya suchi_grah(l, i) {
    vitti lst = l
    vitti idx = i
    yadi (idx < 0) { nivartanam 0 }
    yadi (idx >= lst[0]) { nivartanam 0 }
    vitti d = lst[2]
    nivartanam d[idx]
}

# suchi_sangrah(l, i, v) — set element i. Returns 1 ok / 0 out of bounds.

prakriya suchi_sangrah(l, i, v) {
    vitti lst = l
    vitti idx = i
    vitti val = v
    yadi (idx < 0) { nivartanam 0 }
    yadi (idx >= lst[0]) { nivartanam 0 }
    vitti d = lst[2]
    d[idx] = val
    nivartanam 1
}

# suchi_maap(l) — element count.

prakriya suchi_maap(l) {
    nivartanam l[0]
}

# suchi_nivesh(l, i, v) — insert v before index i (i == len
# appends). Returns 1 ok / 0 out of bounds or allocation failure.

prakriya suchi_nivesh(l, i, v) {
    vitti lst = l
    vitti idx = i
    vitti val = v
    vitti d = 0
    vitti k = 0
    yadi (idx < 0) { nivartanam 0 }
    yadi (idx > lst[0]) { nivartanam 0 }
    yadi (lst[0] == lst[1]) {
        yadi (suchi_vardh(lst) == 0) { nivartanam 0 }
    }
    d = lst[2]
    k = lst[0]
    yavat (k > idx) {
        d[k] = d[k - 1]
        k = k - 1
    }
    d[idx] = val
    lst[0] = lst[0] + 1
    nivartanam 1
}

# suchi_apanay(l, i) — remove element i, shifting the rest left.
# Returns 1 ok / 0 out of bounds.

prakriya suchi_apanay(l, i) {
    vitti lst = l
    vitti idx = i
    vitti d = 0
    vitti k = 0
    yadi (idx < 0) { nivartanam 0 }
    yadi (idx >= lst[0]) { nivartanam 0 }
    d = lst[2]
    k = idx
    yavat (k < lst[0] - 1) {
        d[k] = d[k + 1]
        k = k + 1
    }
    lst[0] = lst[0] - 1
    nivartanam 1
}

# suchi_vinimay(l, i, j) — vinimay elements i and j (WS2, R20). Returns 1
# ok / 0 if either index is out of bounds (then nothing changes).
# Before this, swapping meant a temp variable plus two suchi_sangrah
# calls at every call site.

prakriya suchi_vinimay(l, i, j) {
    vitti lst = l
    vitti a = i
    vitti b = j
    vitti d = 0
    vitti t = 0
    yadi (a < 0) { nivartanam 0 }
    yadi (a >= lst[0]) { nivartanam 0 }
    yadi (b < 0) { nivartanam 0 }
    yadi (b >= lst[0]) { nivartanam 0 }
    d = lst[2]
    t = d[a]
    d[a] = d[b]
    d[b] = t
    nivartanam 1
}

# suchi_viparyay(l) — reverse the list in place (WS3, R20). Two-pointer
# vinimay, same shape as khand_viparyay. Returns 1. Before this, reversing
# a list meant a hand-written two-index loop at every call site.

prakriya suchi_laghu(l, ok) {
    yadi (l[0] == 0) {
        ok[0] = 0
        nivartanam 0
    }
    ok[0] = 1
    nivartanam laghu(l[2], l[0])
}

# suchi_adhik(l, ok) — largest element (WS2, R21); ok[0] 1, or 0 if
# the list is empty (returns 0 then). See suchi_laghu.

prakriya suchi_adhik(l, ok) {
    yadi (l[0] == 0) {
        ok[0] = 0
        nivartanam 0
    }
    ok[0] = 1
    nivartanam adhik(l[2], l[0])
}

# suchi_yog(l) — sum of the elements (WS2, R21); 0 for an empty list
# (well-defined, no ok channel needed). Before this, the caller wrote
# the sum loop by hand or called shreni.smlib's yog on l[2].

prakriya suchi_yog(l) {
    nivartanam yog(l[2], l[0])
}

# suchi_gan(l, v) — number of occurrences of v (WS2, R21).
# Before this, the caller wrote the count loop by hand or called
# shreni.smlib's gan on l[2].

prakriya suchi_gan(l, v) {
    nivartanam gan(l[2], l[0], v)
}

# suchi_anwesh(l, v) — first index of v, or -1 (WS2, R23). List-shaped
# form of shreni.smlib's anwesh_sarak; before, the caller called
# anwesh_sarak(l[2], suchi_maap(l), v) by hand.

prakriya suchi_anwesh(l, v) {
    nivartanam anwesh_sarak(l[2], l[0], v)
}

# suchi_asti_sorted(l) — 1 if the elements are in non-decreasing order,
# else 0; empty and single-element lists are sorted (WS2, R23).
# List-shaped form of shreni.smlib's asti_sorted.

prakriya suchi_rikta(l) {
    vitti d = l[2]
    vitti i = 0
    yavat (i < l[1]) {
        d[i] = 0
        i = i + 1
    }
    l[0] = 0
    nivartanam 1
}

# suchi_antah(l, v) — 1 if any element equals v, else 0.

prakriya suchi_antah(l, v) {
    vitti lst = l
    vitti val = v
    vitti d = lst[2]
    vitti i = 0
    yavat (i < lst[0]) {
        yadi (d[i] == val) { nivartanam 1 }
        i = i + 1
    }
    nivartanam 0
}

# suchi_kramank(l, v) — first index with value v, or -1 if absent.

prakriya suchi_kramank(l, v) {
    vitti lst = l
    vitti val = v
    vitti d = lst[2]
    vitti i = 0
    yavat (i < lst[0]) {
        yadi (d[i] == val) { nivartanam i }
        i = i + 1
    }
    nivartanam 0 - 1
}

# --- stacks (built on the same list storage) ---

# chay_khip(l, v) — push v. Returns 1 ok / 0 allocation failure.

prakriya chay_khip(l, v) {
    nivartanam suchi_khip(l, v)
}

# chay_apanay(l, ok) — pop the top value; sets ok[0] to 1 on success,
# 0 when the stack is empty (returns 0 then).

prakriya chay_avalok(l, ok) {
    vitti lst = l
    vitti okp = ok
    vitti d = 0
    yadi (lst[0] == 0) {
        okp[0] = 0
        nivartanam 0
    }
    d = lst[2]
    okp[0] = 1
    nivartanam d[lst[0] - 1]
}

# chay_rikta(l) — 1 if the stack is empty, else 0.

prakriya avali_antah(q, v) {
    vitti qu = q
    vitti val = v
    vitti d = qu[2]
    vitti k = 0
    yavat (k < qu[0]) {
        yadi (d[(qu[3] + k) % qu[1]] == val) { nivartanam 1 }
        k = k + 1
    }
    nivartanam 0
}

# avali_rikta(q) — empty the queue in place (WS2, R19): same handle,
# same capacity, head reset to 0, and the ring data ZEROED — the
# dequeued dead space held stale values readable through q[2], the
# same hazard nighantu_rikta/suchi_rikta close. Capacity never shrinks.
# Returns 1.

prakriya avali_rikta(q) {
    vitti d = q[2]
    vitti i = 0
    yavat (i < q[1]) {
        d[i] = 0
        i = i + 1
    }
    q[0] = 0
    q[3] = 0
    nivartanam 1
}

# avali_shunya(q) — 1 if the queue is empty, else 0.

prakriya avali_shunya(q) {
    yadi (q[0] == 0) { nivartanam 1 }
    nivartanam 0
}

# avali_maap(q) — element count.

prakriya avali_maap(q) {
    nivartanam q[0]
}

prakriya varna_tak_ank(buf, n, ok) {
    vitti src = buf
    vitti cnt = n
    vitti okp = ok
    okp[0] = 1
    yadi (cnt == 0) {
        okp[0] = 0
        nivartanam 0
    }
    vitti neg = 0
    vitti p = 0
    yadi (src[0] == 45) {
        neg = 1
        p = 1
        yadi (cnt == 1) {
            okp[0] = 0
            nivartanam 0
        }
    }
    vitti val = 0
    yavat (p < cnt) {
        vitti c = src[p]
        yadi (c < 48) {
            okp[0] = 0
            nivartanam 0
        }
        yadi (c > 57) {
            okp[0] = 0
            nivartanam 0
        }
        yadi (val > 922337203685477580) {
            okp[0] = 0
            nivartanam 0
        }
        yadi (val == 922337203685477580) {
            yadi (neg == 1) {
                yadi ((c - 48) > 8) {
                    okp[0] = 0
                    nivartanam 0
                }
            } anya {
                yadi ((c - 48) > 7) {
                    okp[0] = 0
                    nivartanam 0
                }
            }
        }
        val = val * 10 + (c - 48)
        p = p + 1
    }
    yadi (neg == 1) { val = 0 - val }
    nivartanam val
}

# ank_tak_aadhar_varna(n, base, out) — write n in any base 2..36 into out
# as character codes (0-9, a-z). Returns count. No util_chinha handling; n >= 0.
# Base outside 2..36: terminator only, returns 0 (base 0 trapped
# with SIGFPE, base 1 looped forever past the buffer).

prakriya ank_tak_aadhar_varna(n, base, out) {
    vitti val = n
    vitti b = base
    vitti dst = out
    vitti rev = nirmmita(70 * 8)
    yadi (rev == 0) {
        dst[0] = 0
        nivartanam 0
    }
    vitti rlen = 0
    yadi (b < 2) {
        dst[0] = 0
        nivartanam 0
    }
    yadi (b > 36) {
        dst[0] = 0
        nivartanam 0
    }
    yadi (val == 0) {
        dst[0] = 48
        dst[1] = 0
        nivartanam 1
    }
    yavat (val > 0) {
        vitti d = val % b
        yadi (d < 10) {
            rev[rlen] = d + 48
        } anya {
            rev[rlen] = d + 87
        }
        rlen = rlen + 1
        val = val / b
    }
    vitti p = 0
    yavat (p < rlen) {
        dst[p] = rev[rlen - 1 - p]
        p = p + 1
    }
    dst[rlen] = 0
    nivartanam rlen
}

# varna_tak_ank_aadhar(buf, n, base, ok) — parse first n char codes of buf in
# `base` (2/8/10/16). Sets ok[0]. Returns value.

prakriya varna_tak_ank_aadhar(buf, n, base, ok) {
    vitti src = buf
    vitti cnt = n
    vitti b = base
    vitti okp = ok
    okp[0] = 1
    yadi (cnt == 0) {
        okp[0] = 0
        nivartanam 0
    }
    vitti val = 0
    vitti p = 0
    yavat (p < cnt) {
        vitti c = src[p]
        vitti d = 0 - 1
        yadi (c >= 48) {
            yadi (c <= 57) { d = c - 48 }
        }
        yadi (c >= 97) {
            yadi (c <= 102) { d = c - 87 }
        }
        yadi (c >= 65) {
            yadi (c <= 70) { d = c - 55 }
        }
        yadi (d < 0) {
            okp[0] = 0
            nivartanam 0
        }
        yadi (d >= b) {
            okp[0] = 0
            nivartanam 0
        }
        yadi (val > 9223372036854775807 / b) {
            okp[0] = 0
            nivartanam 0
        }
        yadi (val == 9223372036854775807 / b) {
            yadi (d > 9223372036854775807 - val * b) {
                okp[0] = 0
                nivartanam 0
            }
        }
        val = val * b + d
        p = p + 1
    }
    nivartanam val
}

# pad_vam(out, count, width, fill) — left-pad the `count` character codes
# in mala `out` to `width` using fill character code `fill`, in place.
# Returns the new count (width if width > count, else count).
# Caller must allocate >= width cells.

prakriya varna_tak_dashm(buf, n, ok) {
    vitti src = buf
    vitti cnt = n
    vitti okp = ok
    okp[0] = 1
    yadi (cnt == 0) {
        okp[0] = 0
        nivartanam 0.0
    }
    vitti neg = 0
    vitti p = 0
    yadi (src[0] == 45) {
        neg = 1
        p = 1
        yadi (cnt == 1) {
            okp[0] = 0
            nivartanam 0.0
        }
    }
    vitti mant = 0
    vitti ndig = 0
    vitti exp10 = 0
    vitti seen = 0
    vitti done = 0
    yavat ((p < cnt) && (done == 0)) {
        vitti c1 = src[p]
        yadi ((c1 == 46) || (c1 == 101) || (c1 == 69)) {
            done = 1
        } anya {
            yadi (c1 < 48) {
                okp[0] = 0
                nivartanam 0.0
            }
            yadi (c1 > 57) {
                okp[0] = 0
                nivartanam 0.0
            }
            yadi (ndig < 18) {
                mant = mant * 10 + (c1 - 48)
                ndig = ndig + 1
            } anya {
                exp10 = exp10 + 1
            }
            seen = seen + 1
            p = p + 1
        }
    }
    yadi (p < cnt) {
        yadi (src[p] == 46) {
            p = p + 1
            done = 0
            yavat ((p < cnt) && (done == 0)) {
                vitti c2 = src[p]
                yadi ((c2 == 101) || (c2 == 69)) {
                    done = 1
                } anya {
                    yadi (c2 < 48) {
                        okp[0] = 0
                        nivartanam 0.0
                    }
                    yadi (c2 > 57) {
                        okp[0] = 0
                        nivartanam 0.0
                    }
                    yadi (ndig < 18) {
                        mant = mant * 10 + (c2 - 48)
                        ndig = ndig + 1
                        exp10 = exp10 - 1
                    }
                    seen = seen + 1
                    p = p + 1
                }
            }
        }
    }
    yadi (seen == 0) {
        okp[0] = 0
        nivartanam 0.0
    }
    yadi (p < cnt) {
        yadi (src[p] == 101) {
            p = p + 1
        } anya {
            yadi (src[p] == 69) {
                p = p + 1
            } anya {
                okp[0] = 0
                nivartanam 0.0
            }
        }
        vitti eneg = 0
        yadi (p < cnt) {
            yadi (src[p] == 45) {
                eneg = 1
                p = p + 1
            }
        }
        yadi (p >= cnt) {
            okp[0] = 0
            nivartanam 0.0
        }
        vitti e = 0
        vitti eseen = 0
        yavat (p < cnt) {
            vitti c3 = src[p]
            yadi (c3 < 48) {
                okp[0] = 0
                nivartanam 0.0
            }
            yadi (c3 > 57) {
                okp[0] = 0
                nivartanam 0.0
            }
            yadi (e < 1000) {
                e = e * 10 + (c3 - 48)
            }
            eseen = eseen + 1
            p = p + 1
        }
        yadi (eseen == 0) {
            okp[0] = 0
            nivartanam 0.0
        }
        yadi (eneg == 1) {
            exp10 = exp10 - e
        } anya {
            exp10 = exp10 + e
        }
    }
    yadi (p != cnt) {
        okp[0] = 0
        nivartanam 0.0
    }
    yadi (mant == 0) {
        nivartanam 0.0
    }
    yadi (exp10 > 308) {
        okp[0] = 0
        nivartanam 0.0
    }
    yadi (exp10 < -308) {
        nivartanam 0.0
    }
    dasham val = mant
    yadi (exp10 > 0) {
        vitti k = 0
        yavat (k < exp10) {
            val = val * 10.0
            k = k + 1
        }
    } anya {
        vitti k2 = 0
        yavat (k2 < (0 - exp10)) {
            val = val / 10.0
            k2 = k2 + 1
        }
    }
    # Overflow guard: the exp10 > 308 check does not catch
    # mant > 1 with exp10 == 308 (e.g. "9e308" returned inf with
    # ok = 1). Halving is exact for finite doubles, so val / 2
    # == val iff val is infinite — that is the overflow.
    yadi (val != 0.0) {
        yadi (val / 2.0 == val) {
            okp[0] = 0
            nivartanam 0.0
        }
    }
    yadi (neg == 1) { val = 0.0 - val }
    nivartanam val
}

prakriya asti_ank_akshar(s, i) {
    vitti c = akshar(s, i)
    yadi (c >= 48 && c <= 57) { nivartanam 1 }
    nivartanam 0
}

# asti_unnat_akshar(s, i) — 1 if s[i] is an uppercase letter ('A'-'Z'), else 0.

prakriya asti_unnat_akshar(s, i) {
    vitti c = akshar(s, i)
    yadi (c >= 65 && c <= 90) { nivartanam 1 }
    nivartanam 0
}

# asti_avanat_akshar(s, i) — 1 if s[i] is a lowercase letter ('a'-'z'), else 0.

prakriya asti_avanat_akshar(s, i) {
    vitti c = akshar(s, i)
    yadi (c >= 97 && c <= 122) { nivartanam 1 }
    nivartanam 0
}

# asti_akshar_akshar(s, i) — 1 if s[i] is any letter (A-Z or a-z), else 0.

prakriya asti_akshar_akshar(s, i) {
    vitti c = akshar(s, i)
    yadi (c >= 65 && c <= 90) { nivartanam 1 }
    yadi (c >= 97 && c <= 122) { nivartanam 1 }
    nivartanam 0
}

# asti_avakash_akshar(s, i) — 1 if s[i] is a space (code 32), else 0.

prakriya asti_avakash_akshar(s, i) {
    vitti c = akshar(s, i)
    nivartanam c == 32
}

# gan_swar(s) — count of lowercase vowels (a, e, i, o, u) in the string s.

prakriya gan_swar(s) {
    vitti n = vartani_aayam(s)
    vitti i = 0
    vitti c = 0
    yavat (i < n) {
        vitti ch = akshar(s, i)
        yadi (ch == 97 || ch == 101 || ch == 105 || ch == 111 || ch == 117) {
            c = c + 1
        }
        i = i + 1
    }
    nivartanam c
}

# gan_akshar(s, code) — count of occurrences of byte code in the string s.

prakriya gan_akshar(s, code) {
    vitti n = vartani_aayam(s)
    vitti i = 0
    vitti c = 0
    yavat (i < n) {
        yadi (akshar(s, i) == code) { c = c + 1 }
        i = i + 1
    }
    nivartanam c
}

# anwesh_akshar(s, code) — index of the first occurrence of byte code in s, or -1.

prakriya anwesh_akshar(s, code) {
    vitti n = vartani_aayam(s)
    vitti i = 0
    yavat (i < n) {
        yadi (akshar(s, i) == code) { nivartanam i }
        i = i + 1
    }
    nivartanam 0 - 1
}

# asti_sarv_ank(s) — 1 if s is non-empty and every character is a digit, else 0.

prakriya asti_sarv_ank(s) {
    vitti n = vartani_aayam(s)
    yadi (n == 0) { nivartanam 0 }
    vitti i = 0
    yavat (i < n) {
        yadi (asti_ank_akshar(s, i) == 0) { nivartanam 0 }
        i = i + 1
    }
    nivartanam 1
}

# unnat_sanket(c) — byte code c converted to uppercase (a-z -> A-Z, other codes unchanged).

prakriya unnat_sanket(c) {
    vitti x = c
    yadi (x >= 97 && x <= 122) { x = x - 32 }
    nivartanam x
}

# avanat_sanket(c) — byte code c converted to lowercase (A-Z -> a-z, other codes unchanged).

prakriya avanat_sanket(c) {
    vitti x = c
    yadi (x >= 65 && x <= 90) { x = x + 32 }
    nivartanam x
}

# varna_sam(a, b) — 1 if strings a and b are byte-identical (same length and bytes), else 0.

prakriya varna_anwesh(hay, hn, needle, nn) {
    vitti h = hay
    vitti hlen = hn
    vitti nd = needle
    vitti nlen = nn
    yadi (nlen < 0) { nivartanam 0 - 1 }
    yadi (nlen == 0) { nivartanam 0 }
    yadi (nlen > hlen) { nivartanam 0 - 1 }
    vitti i = 0
    yavat (i <= hlen - nlen) {
        vitti match = 1
        vitti j = 0
        yavat (j < nlen) {
            yadi (h[i + j] != nd[j]) { match = 0 }
            j = j + 1
        }
        yadi (match == 1) { nivartanam i }
        i = i + 1
    }
    nivartanam 0 - 1
}

# varna_antah(hay, hn, needle, nn) — 1 if needle occurs in hay, else 0.

prakriya varna_antah(hay, hn, needle, nn) {
    yadi (varna_anwesh(hay, hn, needle, nn) >= 0) { nivartanam 1 }
    nivartanam 0
}

# varna_pratisthap(src, sn, find, fn, repl, out) — copy src to out,
# replacing every (non-overlapping) occurrence of find with repl.
# repl is 0-terminated (its length is derived) — repl cannot be a
# slice; copy the slice into a terminated cell array first (see
# strb.smlib header, slice-boundary rules). Returns the new count.
# Caller allocates generously.

prakriya varna_pratisthap(src, sn, find, fn, repl, out) {
    vitti s = src
    vitti slen = sn
    vitti f = find
    vitti flen = fn
    vitti r = repl
    vitti dst = out
    # measure repl (0-terminated)
    vitti rlen = 0
    yavat (r[rlen] != 0) { rlen = rlen + 1 }
    vitti wpos = 0
    vitti rpos = 0
    yadi (flen <= 0) {
        # empty find: copy verbatim (flen < 0 used to loop
        # forever, rpos decreasing, writing past out — SIGSEGV).
        yavat (rpos < slen) {
            dst[wpos] = s[rpos]
            wpos = wpos + 1
            rpos = rpos + 1
        }
        dst[wpos] = 0
        nivartanam wpos
    }
    yavat (rpos < slen) {
        # check for find at rpos
        vitti match = 1
        yadi (rpos + flen > slen) {
            match = 0
        } anya {
            vitti j = 0
            yavat (j < flen) {
                yadi (s[rpos + j] != f[j]) { match = 0 }
                j = j + 1
            }
        }
        yadi (match == 1) {
            vitti k = 0
            yavat (k < rlen) {
                dst[wpos] = r[k]
                wpos = wpos + 1
                k = k + 1
            }
            rpos = rpos + flen
        } anya {
            dst[wpos] = s[rpos]
            wpos = wpos + 1
            rpos = rpos + 1
        }
    }
    dst[wpos] = 0
    nivartanam wpos
}

# varna_bhed(src, sn, sep, sepn, parts, maxparts) — split src on sep.
# parts is a flat buffer holding length-prefixed segments:
#   [len0, c0, c1, ..., len1, c0, ...]
# To recover segment i: walk from parts[0], skipping (1 + len) cells per
# segment; the length is at the segment's start. Returns segment count
# (capped at maxparts). Empty separator: no split (one segment).

prakriya varna_bhed(src, sn, sep, sepn, parts, maxparts) {
    vitti s = src
    vitti slen = sn
    vitti sp = sep
    vitti splen = sepn
    vitti dst = parts
    vitti maxp = maxparts
    # empty input: one empty segment
    yadi (slen == 0) {
        dst[0] = 0
        nivartanam 1
    }
    # empty separator: one segment (the whole input). splen < 0
    # is invalid: same result (the old code looped forever).
    yadi (splen <= 0) {
        dst[0] = slen
        vitti ci = 0
        yavat (ci < slen) {
            dst[1 + ci] = s[ci]
            ci = ci + 1
        }
        nivartanam 1
    }
    vitti nseg = 0
    vitti wpos = 0
    vitti segstart = 0
    vitti rpos = 0
    vitti done = 0
    vitti fpos = 0
    vitti si = 0
    vitti sj = 0
    vitti smatch = 0
    vitti segend = 0
    vitti seglen = 0
    vitti sk = 0
    yavat (done == 0) {
        # find sep at or after rpos
        fpos = 0 - 1
        si = rpos
        yavat (si + splen <= slen) {
            smatch = 1
            sj = 0
            yavat (sj < splen) {
                yadi (s[si + sj] != sp[sj]) { smatch = 0 }
                sj = sj + 1
            }
            yadi (smatch == 1) {
                fpos = si
                si = slen
            } anya {
                si = si + 1
            }
        }
        segend = slen
        yadi (fpos >= 0) { segend = fpos }
        yadi (nseg < maxp) {
            seglen = segend - segstart
            dst[wpos] = seglen
            wpos = wpos + 1
            sk = segstart
            yavat (sk < segend) {
                dst[wpos] = s[sk]
                wpos = wpos + 1
                sk = sk + 1
            }
            nseg = nseg + 1
        }
        yadi (fpos < 0) {
            done = 1
        } anya {
            segstart = fpos + splen
            rpos = segstart
            yadi (rpos >= slen) {
                yadi (nseg < maxp) {
                    dst[wpos] = 0
                    nseg = nseg + 1
                }
                done = 1
            }
        }
    }
    nivartanam nseg
}

# varna_yuj(parts, count, sep, sepn, out) — inverse of varna_bhed for the
# length-prefixed format. Joins `count` segments with sep. Returns new count.

prakriya varna_chhid(src, sn, out) {
    vitti s = src
    vitti slen = sn
    vitti dst = out
    vitti lo = 0
    vitti go = 1
    yavat (go == 1) {
        yadi (lo >= slen) {
            go = 0
        } anya {
            yadi (s[lo] == 32) { lo = lo + 1 } anya { go = 0 }
        }
    }
    vitti hi = slen
    vitti go2 = 1
    yavat (go2 == 1) {
        yadi (hi <= lo) {
            go2 = 0
        } anya {
            yadi (s[hi - 1] == 32) { hi = hi - 1 } anya { go2 = 0 }
        }
    }
    vitti wpos = 0
    vitti k = lo
    yavat (k < hi) {
        dst[wpos] = s[k]
        wpos = wpos + 1
        k = k + 1
    }
    dst[wpos] = 0
    nivartanam wpos
}

# varna_unnat(src, sn, out) / varna_avanat — ASCII case conversion.
# sn < 0: empty output (the old code wrote the terminator at
# out[-1], an out-of-bounds write before the buffer).

prakriya varna_unnat(src, sn, out) {
    vitti s = src
    vitti slen = sn
    vitti dst = out
    vitti i = 0
    yadi (slen < 0) {
        dst[0] = 0
        nivartanam 0
    }
    yavat (i < slen) {
        vitti c = s[i]
        yadi (c >= 97) {
            yadi (c <= 122) { c = c - 32 }
        }
        dst[i] = c
        i = i + 1
    }
    dst[slen] = 0
    nivartanam slen
}

# varna_avanat(src, sn, out) — copies src (sn qword cells) to out with A-Z lowercased, NUL-terminated; returns sn (0 for sn < 0).

prakriya varna_avanat(src, sn, out) {
    vitti s = src
    vitti slen = sn
    vitti dst = out
    vitti i = 0
    yadi (slen < 0) {
        dst[0] = 0
        nivartanam 0
    }
    yavat (i < slen) {
        vitti c = s[i]
        yadi (c >= 65) {
            yadi (c <= 90) { c = c + 32 }
        }
        dst[i] = c
        i = i + 1
    }
    dst[slen] = 0
    nivartanam slen
}

# varna_aadi(src, sn, pre, pn) / varna_ant — 0/1.
# A negative prefix/suffix length is invalid: 0 (the old code
# treated it as empty and returned 1).

prakriya varna_aadi(src, sn, pre, pn) {
    vitti s = src
    vitti slen = sn
    vitti pr = pre
    vitti plen = pn
    yadi (plen < 0) { nivartanam 0 }
    yadi (plen > slen) { nivartanam 0 }
    vitti i = 0
    yavat (i < plen) {
        yadi (s[i] != pr[i]) { nivartanam 0 }
        i = i + 1
    }
    nivartanam 1
}

# varna_ant(src, sn, suf, sn2) — 1 if the src string (sn cells) ends with suf (sn2 cells), else 0.

prakriya varna_ant(src, sn, suf, sn2) {
    vitti s = src
    vitti slen = sn
    vitti sf = suf
    vitti sflen = sn2
    yadi (sflen < 0) { nivartanam 0 }
    yadi (sflen > slen) { nivartanam 0 }
    vitti i = 0
    yavat (i < sflen) {
        yadi (s[slen - sflen + i] != sf[i]) { nivartanam 0 }
        i = i + 1
    }
    nivartanam 1
}

# varna_tul(a, an, b, bn) — -1 / 0 / 1 (lexicographic by char code).

prakriya varna_tul(a, an, b, bn) {
    vitti x = a
    vitti xn = an
    vitti y = b
    vitti yn = bn
    vitti i = 0
    vitti n = xn
    yadi (yn < n) { n = yn }
    yavat (i < n) {
        yadi (x[i] < y[i]) { nivartanam 0 - 1 }
        yadi (x[i] > y[i]) { nivartanam 1 }
        i = i + 1
    }
    yadi (xn < yn) { nivartanam 0 - 1 }
    yadi (xn > yn) { nivartanam 1 }
    nivartanam 0
}

# varna_viparyay(src, sn, out) — copy the cell array reversed into out
# (WS1, R20). Cell-array form of khand_viparyay: the same two-pointer
# vinimay, so it is safe in place (src == out works). Writes a 0
# terminator cell at out[sn]. Returns sn. sn <= 0 writes only the
# terminator, returns 0.

prakriya varna_gan(hay, hn, needle, nn) {
    vitti h = hay
    vitti hlen = hn
    vitti nd = needle
    vitti nlen = nn
    vitti pos = 0
    vitti c = 0
    vitti f = 0
    yadi (nlen <= 0) { nivartanam 0 }
    yavat (pos <= hlen - nlen) {
        f = varna_anwesh(h + pos * 8, hlen - pos, nd, nlen)
        yadi (f < 0) { nivartanam c }
        c = c + 1
        pos = pos + f + nlen
    }
    nivartanam c
}
